import JSON

"""
	gen( p, a, b, name )

Generate fixture data and write to file.

The quantile is evaluated in extended precision from the textbook formula `(1 - (1-p)^(1/b))^(1/a)`, as forming `1-p` in double precision rounds away the low-order bits of `p` (all of them for `p < 2^-53`).

# Arguments

* `p`: input probability
* `a`: first shape parameter
* `b`: second shape parameter
* `name::AbstractString`: output filename
"""
function gen( p, a, b, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( ( 1 .- ( 1 .- BigFloat.( p ) ) .^ ( 1 ./ BigFloat.( b ) ) ) .^ ( 1 ./ BigFloat.( a ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("p", p),
		("a", a),
		("b", b),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Random values:
p = rand( 1000 );
a = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
b = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
gen( p, a, b, "data.json" );

# Small `p` (`a` is a power of two, so that `1/a` is exact and the test measures the error from `1-p`):
p = exp10.( range( -300.0, stop = -1.0, length = 1000 ) );
a = repeat( [ 1.0, 2.0, 4.0, 8.0 ], 250 );
b = ( rand( 1000 ) .* 5.0 ) .+ 0.5;
gen( p, a, b, "small_p.json" );
